#include <mach-o/loader.h>

// DYLD_INSERT_LIBRARIES is inherited by every process Roblox spawns
// (RobloxCrashHandler, RobloxMenuBar), so the host image has to be located by
// name rather than by index: index 0 is whichever executable was launched and
// index 1 is this dylib itself, neither of which is reliably RobloxPlayer.
struct HostImage {
    uintptr_t slide = 0;
    bool found = false;
    // dyld owns this string for the life of the image, so a borrowed pointer is
    // enough. getcustomasset derives the app bundle's content directory from it
    // rather than hardcoding /Applications.
    const char* path = nullptr;
};

inline HostImage findHostImage()
{
    const uint32_t count = _dyld_image_count();
    for (uint32_t i = 0; i < count; i++) {
        const mach_header* header = _dyld_get_image_header(i);
        if (!header || header->filetype != MH_EXECUTE)
            continue;

        const char* path = _dyld_get_image_name(i);
        if (!path)
            continue;

        const char* name = std::strrchr(path, '/');
        name = name ? name + 1 : path;
        if (std::strcmp(name, "RobloxPlayer") != 0)
            continue;

        return { static_cast<uintptr_t>(_dyld_get_image_vmaddr_slide(i)), true, path };
    }
    return {};
}

// Resolved on first use: __attribute__((constructor)) entries run before the
// dynamic initializers for namespace-scope globals, so a plain global here
// would still read as zero from init().
inline const HostImage& hostImage()
{
    static const HostImage image = findHostImage();
    return image;
}

inline uintptr_t rebase(uintptr_t addr)
{
    return addr + hostImage().slide;
}

